import {propRole} from './prop-role.js';

const FPS=30;
// Seek inside a frame, then trust the compositor's PTS rather than rounded currentTime.
export function localMaterialFrameTime(index,frameCount){
  if(!Number.isInteger(frameCount)||frameCount<1||!Number.isFinite(index))throw new Error('视频帧信息尚未读取。');
  return Math.max(0,Math.min(frameCount-1,Math.round(index)))/FPS+0.0001;
}
export function localMaterialFrameController(video,{frameCount,onChange=()=>{},onError=()=>{}}){
  let presented=null,requested=null,pending=true,callback=null,disposed=false,playing=false;
  const count=()=>Math.max(1,Math.round(frameCount()));
  const current=()=>({frame:presented,requested,ready:!disposed&&!pending&&video.paused&&!video.seeking&&video.readyState>=2&&presented!==null});
  const changed=()=>{if(!disposed)onChange(current());};
  const confirm=()=>{if(presented!==null&&presented===requested&&!video.seeking&&video.readyState>=2)pending=false;changed();};
  const watch=()=>{if(disposed||callback!==null||!video.requestVideoFrameCallback)return;callback=video.requestVideoFrameCallback((_,metadata)=>{callback=null;if(disposed)return;const value=Math.round(metadata.mediaTime*FPS);presented=Number.isFinite(value)&&value>=0&&value<count()?value:null;confirm();watch();});};
  const reset=()=>{if(callback!==null)video.cancelVideoFrameCallback?.(callback);callback=null;presented=null;pending=true;playing=false;changed();watch();};
  const seekFrame=index=>{if(disposed||!Number.isFinite(index))return;requested=Math.max(0,Math.min(count()-1,Math.round(index)));pending=true;playing=false;changed();video.pause();watch();if(video.readyState>=1)video.currentTime=localMaterialFrameTime(requested,count());};
  const seekTime=time=>{if(Number.isFinite(time))seekFrame(Math.round(time*FPS));};
  const events={
    emptied:reset,
    loadedmetadata:()=>seekFrame(requested??0),
    loadeddata:()=>{watch();confirm();},
    seeking:()=>{pending=true;changed();},
    seeked:confirm,
    play:()=>{playing=true;pending=true;changed();watch();},
    pause:()=>{if(playing){playing=false;seekFrame(presented??Math.floor(video.currentTime*FPS));}},
    ended:()=>seekFrame(count()-1),
    error:()=>{reset();onError();},
  };
  for(const[name,handler]of Object.entries(events))video.addEventListener(name,handler);
  if(!video.requestVideoFrameCallback)onError('当前播放器无法确认实际视频帧，请更新软件后再校准。');
  watch();
  return {current,reset,seekFrame,seekTime,step:delta=>seekFrame(((pending?requested:presented)??0)+delta),pause:()=>{video.pause();seekFrame(presented??Math.floor(video.currentTime*FPS));},dispose:()=>{disposed=true;if(callback!==null)video.cancelVideoFrameCallback?.(callback);for(const[name,handler]of Object.entries(events))video.removeEventListener(name,handler);}};
}
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const assets=job=>job?.recipe?.story?.assets||[];
const actors=job=>assets(job).filter(a=>a.type==='character');
const materials=job=>assets(job).filter(a=>propRole(a,job?.recipe?.edits?.assets?.[a.id])==='material');
export const canRepairLocalMaterial=job=>job?.state==='completed'&&job.workflow==='studio'&&job.source?.duration>0&&actors(job).length>0&&materials(job).length>0;
export const localMaterialButton=(job,{enabled=true}={})=>canRepairLocalMaterial(job)?`<button class="secondary" data-action="local-material-job" data-id="${esc(job.id)}" ${enabled?'':'disabled title="本地涂抹处理组件尚未安装，请安装组件后重新打开软件。本地处理不需要连接视频服务。"'}>保留原片真实涂抹</button>${enabled?'':'<span class="asset-target-scope">本地涂抹处理组件尚未安装，安装后重新打开软件即可使用。</span>'}`:'';

export function localMaterialDefaults(job){
  const material=materials(job)[0],action=(job.recipe?.story?.actions||[]).find(a=>a.type==='spread'&&a.propId===material?.id);
  const requestedStart=Number(action?.start)||0;
  const start=requestedStart>=0&&requestedStart<job.source.duration?requestedStart:0;
  const end=Math.min(job.source.duration,Number(action?.end)>start?Number(action.end):start+5);
  return{sourceStart:start,sourceEnd:end,targetStart:start,targetEnd:end,sourceActorId:action?.characterId||actors(job)[0]?.id,targetActorId:action?.characterId||actors(job)[0]?.id,materialAssetId:material?.id};
}
export function localMaterialRange(start,end,duration){
  if(![start,end,duration].every(Number.isFinite)||start<0||end<=start||duration<=0)return null;
  const startFrame=Math.round(start*FPS),endFrame=Math.round(end*FPS),frames=endFrame-startFrame;
  return frames>0&&frames<=450&&endFrame<=Math.round(duration*FPS)?{startFrame,frames}:null;
}
export function localMaterialCoordinate(x,y,rect){
  if(![x,y,rect?.left,rect?.top,rect?.width,rect?.height].every(Number.isFinite)||rect.width<=0||rect.height<=0)return null;
  return{x:Math.max(0,Math.min(1,(x-rect.left)/rect.width)),y:Math.max(0,Math.min(1,(y-rect.top)/rect.height))};
}
export const emptyLocalMaterialCalibration=()=>({sourceRegion:[],targetRegion:[],sourceSkinPoints:[],targetSkinPoints:[],anchorPair:null,targetMaterialKeyframes:[],appearanceKeyframes:[],postCutCleanup:[],framePairs:[],framePairAnchors:[],shots:[],handKeyframes:[],reviewed:false,donorReviewed:false});
export function localMaterialCalibrationForSave(calibration){
  return {...calibration,handKeyframes:calibration.handKeyframes.map(key=>({side:key.side,frameIndex:key.frameIndex,strokes:structuredClone(key.strokes||[]),...(key.uploadId?{uploadId:key.uploadId}:{})}))};
}
export function localMaterialHandKeyframe(calibration,side,frameIndex){
  if(!['source','target'].includes(side)||!Number.isInteger(frameIndex)||frameIndex<0)throw new Error('请选择有效的画面。');
  let key=calibration.handKeyframes.find(item=>item.side===side&&item.frameIndex===frameIndex);
  if(!key){key={side,frameIndex,strokes:[]};calibration.handKeyframes.push(key);calibration.handKeyframes.sort((a,b)=>a.frameIndex-b.frameIndex||a.side.localeCompare(b.side));}
  return key;
}
export function localMaterialCalibrationIssues(calibration,donor,sourceSkinReference=null,appearanceReconstruction={enabled:false}){
  const issues=[],shots=calibration.shots||[],material=shots.filter(shot=>(shot.mode||'material')==='material');
  const inShot=(shot,side,index)=>index>=shot[side+'StartFrame']&&index<shot[side+'StartFrame']+shot[side+'Frames'];
  const protection=(side,shot)=>calibration.handKeyframes.some(k=>k.side===side&&(!shot||inShot(shot,side,k.frameIndex))&&(k.uploadId||k.strokes.some(s=>s.mode==='protect'&&s.points.length)));
  if(!shots.length)issues.push('请保存完整镜头范围，并选择各镜头的处理方式');
  if(material.length||!shots.length){
    if(calibration.sourceRegion.length<3)issues.push('请圈出原片参考皮肤区域，包含膏体和周围裸肤');
    if(calibration.targetRegion.length<3)issues.push('请圈出成片需要修复的同一块皮肤');
    if((calibration.sourceSkinPoints||[]).length<4)issues.push('请在原片膏体周围干净皮肤上取至少4个点，避开手和厚膏');
    if(!calibration.anchorPair||!material.some(shot=>['source','target'].every(side=>inShot(shot,side,calibration.anchorPair[side+'Frame']))))issues.push('请使用同一涂抹镜头的两帧作为标定，并在该帧圈选、取肤色');
    for(const[ index,shot]of(material.length?material:[null]).entries())for(const side of ['source','target'])if(!protection(side,shot))issues.push(`请标记第${index+1}个涂抹镜头${side==='source'?'原片':'当前人物'}的手和长指甲保护范围`);
  }else if(!(calibration.postCutCleanup||[]).length)issues.push('全部镜头都保留原画面，没有修复内容；请选择涂抹镜头或明确圈出切镜后的多余膏体');
  else if(!protection('target'))issues.push('局部残留清理仍需保护当前人物的手和长指甲');
  const needGlobalDonor=material.length>0||!shots.length||(calibration.postCutCleanup||[]).some(item=>!Number.isInteger(item.donorFrameIndex));
  if(needGlobalDonor&&!donor)issues.push('请选择当前人物自己的干净肤质图或干净帧');
  if(needGlobalDonor&&!calibration.donorReviewed)issues.push('请确认干净肤质来自当前目标人物');
  if(!calibration.reviewed)issues.push('请检查全部风险帧并确认校准');if((calibration.postCutCleanup||[]).some(item=>!item.reviewed||item.region.length<3))issues.push('请完成并核对切镜后的残留选区');
  if(sourceSkinReference&&(!sourceSkinReference.reviewed||!material.some(shot=>inShot(shot,'source',sourceSkinReference.frameIndex))))issues.push('原片推匀参考必须位于跟随原片涂抹的源镜头，并已人工确认');
  if(!material.length&&calibration.anchorPair)issues.push('全部镜头保留时，请清空材料标定，只处理明确圈出的残留区域');
  for(const item of calibration.postCutCleanup||[])if(Number.isInteger(item.donorFrameIndex)&&!shots.some(shot=>shot.mode==='preserve'&&item.targetStartFrame>=shot.targetStartFrame&&item.targetStartFrame+item.targetFrames<=shot.targetStartFrame+shot.targetFrames&&inShot(shot,'target',item.donorFrameIndex)))issues.push('局部清理肤质帧须来自该清理段同一个保留镜头的成片');
  for(const key of calibration.targetMaterialKeyframes||[])if(!key.reviewed||key.region.length<3||!material.some(shot=>inShot(shot,'target',key.frameIndex)))issues.push('旧面霜范围须在对应涂抹镜头内，并已圈选实际旧膜区域');
  if(appearanceReconstruction.enabled===true)for(const key of calibration.appearanceKeyframes||[])if(!key.reviewed||key.region.length<3||!material.some(shot=>inShot(shot,'target',key.frameIndex)))issues.push('局部重建区域须在对应涂抹镜头内，并已核对该帧小区域');
  return issues;
}
export function localMaterialPair(calibration,sourceFrame,targetFrame){
  if(![sourceFrame,targetFrame].every(value=>Number.isInteger(value)&&value>=0))throw new Error('画面对应时间无效。');
  const pairs=(calibration.framePairAnchors||[]).filter(pair=>pair.targetFrame!==targetFrame);
  pairs.push({sourceFrame,targetFrame});pairs.sort((a,b)=>a.targetFrame-b.targetFrame);
  if(pairs.some((pair,index)=>index&&pair.sourceFrame<pairs[index-1].sourceFrame))throw new Error('原片和当前画面须保持相同先后顺序，请重新定位对应帧。');
  calibration.framePairAnchors=pairs;
  calibration.framePairs=[];
}
export function localMaterialSplitShot(calibration,sourceFrame,targetFrame){
  const index=calibration.shots.findIndex(shot=>sourceFrame>shot.sourceStartFrame&&sourceFrame<shot.sourceStartFrame+shot.sourceFrames&&targetFrame>shot.targetStartFrame&&targetFrame<shot.targetStartFrame+shot.targetFrames);
  if(index<0)throw new Error('请把两侧定位到同一次切镜，并避开片段起止点。');
  const old=calibration.shots[index],mode=old.mode?{mode:old.mode}:{};calibration.shots.splice(index,1,{sourceStartFrame:old.sourceStartFrame,sourceFrames:sourceFrame-old.sourceStartFrame,targetStartFrame:old.targetStartFrame,targetFrames:targetFrame-old.targetStartFrame,...mode},{sourceStartFrame:sourceFrame,sourceFrames:old.sourceStartFrame+old.sourceFrames-sourceFrame,targetStartFrame:targetFrame,targetFrames:old.targetStartFrame+old.targetFrames-targetFrame,...mode});
  calibration.framePairAnchors=[];calibration.framePairs=[];
}
export function localMaterialSetAnchor(calibration,sourceFrame,targetFrame){
  const valid=calibration.shots.some(shot=>(shot.mode||'material')==='material'&&sourceFrame>=shot.sourceStartFrame&&sourceFrame<shot.sourceStartFrame+shot.sourceFrames&&targetFrame>=shot.targetStartFrame&&targetFrame<shot.targetStartFrame+shot.targetFrames);
  if(!valid)throw new Error('请把两侧定位到同一个“跟随原片涂抹”的镜头，再开始标定。');
  calibration.anchorPair={sourceFrame,targetFrame};
  for(const name of ['sourceRegion','targetRegion','sourceSkinPoints','targetSkinPoints'])calibration[name]=[];
  calibration.reviewed=false;
}
export function localMaterialShotsHTML(calibration){
  return calibration.shots.map((shot,index)=>`<article class="lm-shot"><p>镜头 ${index+1} · 原片 ${(shot.sourceStartFrame/FPS).toFixed(3)}–${((shot.sourceStartFrame+shot.sourceFrames)/FPS).toFixed(3)}秒 · 成片 ${(shot.targetStartFrame/FPS).toFixed(3)}–${((shot.targetStartFrame+shot.targetFrames)/FPS).toFixed(3)}秒</p><label>处理方式<select data-lm-shot-mode="${index}"><option value="material" ${(shot.mode||'material')==='material'?'selected':''}>跟随原片涂抹</option><option value="preserve" ${shot.mode==='preserve'?'selected':''}>保留这个镜头</option></select></label><button type="button" data-lm-shot-seek="${index}">查看这个镜头</button></article>`).join('')||'<p>保存草稿后显示镜头范围；划出真实切镜，再逐个选择处理方式。</p>';
}
export function localMaterialCleanup(calibration,range,region,donorFrameIndex=null){
  if(!range||region.length<3)throw new Error('请圈出至少3个边缘点，并填写有效的残留清理时间。');
  const withinCutShot=calibration.shots.some((shot,index)=>index>0&&range.startFrame>=shot.targetStartFrame&&range.startFrame+range.frames<=shot.targetStartFrame+shot.targetFrames);
  if(!withinCutShot)throw new Error('请先标出真实切镜，残留清理时间须位于切镜后的同一片段内。');
  if(donorFrameIndex!==null&&!calibration.shots.some(shot=>shot.mode==='preserve'&&range.startFrame>=shot.targetStartFrame&&range.startFrame+range.frames<=shot.targetStartFrame+shot.targetFrames&&Number.isInteger(donorFrameIndex)&&donorFrameIndex>=shot.targetStartFrame&&donorFrameIndex<shot.targetStartFrame+shot.targetFrames))throw new Error('这份肤质参考须来自该残留段同一个保留镜头的成片画面。');
  return{targetStartFrame:range.startFrame,targetFrames:range.frames,region:structuredClone(region),reviewed:true,...(donorFrameIndex!==null?{donorFrameIndex}:{})};
}
export function localMaterialRiskText(risk){
  const reason=String(risk.reason||risk.message||''),code=String(risk.code||'').toLowerCase().replace(/[-_]+/g,' ');
  const text=(code+' '+reason).toLowerCase(),side=risk.side==='target'?'target':risk.side==='source'?'source':/target/.test(text)&&!/source/.test(text)?'target':/source/.test(text)&&!/target/.test(text)?'source':null;
  const name=side==='target'?'成片':side==='source'?'原片':'对应画面';
  if(code.includes('target skin samples inconsistent'))return '成片肤色参考不一致：部分裸肤点可能混入旧面霜或处于不同光照。请返回成片标定画面，在真正干净、没有手遮挡的皮肤上重新取点，并核对当前人物自己的干净肤质参考。';
  if(code.includes('source surface support low'))return '原片在这一时刻缺少可见材料依据，可能有手部遮挡或动作错位；先核对两帧接触位置与手保护，再检查皮肤区域。只选对应皮肤，不要扩大到全脸。';
  if(code.includes('target donor support low'))return '成片干净肤质参考不足：选择当前目标人物同镜头、无厚膏的画面；成片裸肤点可位于修复区域内，只要该点实际没有膏体或手部遮挡。';
  if(code.includes('reference shot mismatch'))return '参考帧不属于对应镜头：原片推匀参考只选同一个涂抹镜头；残留清理肤质只选该段成片的同一个保留镜头。';
  if(code.includes('worker cancelled'))return '本地处理已暂停，已保存标记保留；可继续上次处理。';
  if(code.includes('face tracking uncertain'))return `${name}脸部位置跟随不稳定：回到该镜头，重新选择标定画面、圈选对应皮肤，并补充手部保护。`;
  if(/skin|sample|裸肤|肤色/.test(text)&&/insufficient|lack|low|support|不足|缺少/.test(text))return `${name}肤色参考点不足：回到该侧标定帧，选没有膏体、没有被手挡住的真实皮肤，补点后重新检查。`;
  if(/hand|nail|mask|occlu|手|遮挡/.test(text))return `${name}手部遮挡需要校准：定位这帧，补画手和长指甲保护，再重新检查。`;
  if(/cut|shot|镜头|切镜/.test(text))return '请定位这帧，核对两侧切镜位置和镜头处理方式；展示镜头可选择保留。';
  if(/[\u3400-\u9fff]/u.test(reason))return reason;
  return `${name}需要补充校准：定位这帧，核对皮肤区域、裸肤点、手保护和标定画面，再重新检查。`;
}
export function localMaterialDiagnosticsAtFrames(artifacts,frames,limit=12){
  const allowed=new Set(['target_material_candidate','target_editable','source_hand_exclusion','source_hand_uncertainty']);
  const distance=item=>{const side=item.side|| (item.kind.startsWith('source_')?'source':'target');return Number.isInteger(item.frameIndex)&&Number.isInteger(frames[side+'Frame'])?Math.abs(item.frameIndex-frames[side+'Frame']):Infinity;};
  return (artifacts||[]).filter(item=>allowed.has(item.kind)&&item.id).map((item,index)=>({item,index})).sort((a,b)=>distance(a.item)-distance(b.item)||a.index-b.index).slice(0,limit).map(entry=>entry.item);
}
export function localMaterialRiskGroups(risks){
  const groups=[],last=new Map(),clock=risk=>Number.isInteger(risk.targetFrame)?['target',risk.targetFrame]:Number.isInteger(risk.sourceFrame)?['source',risk.sourceFrame]:[null,null];
  risks.forEach((risk,index)=>{const [side,frame]=clock(risk),key=JSON.stringify([risk.code||'',localMaterialRiskText(risk),risk.side,side,risk.resolved===true]),previous=last.get(key);if(previous&&frame!==null&&frame===previous.endFrame+1){previous.indices.push(index);previous.endFrame=frame;previous.lastRisk=risk;}else{const group={firstIndex:index,indices:[index],clockSide:side,startFrame:frame,endFrame:frame,firstRisk:risk,lastRisk:risk,text:localMaterialRiskText(risk)};groups.push(group);last.set(key,group);}});
  return groups;
}
export function localMaterialRiskGroupsHTML(risks){
  const groups=localMaterialRiskGroups(risks),stamp=frame=>(frame/FPS).toFixed(3)+'秒';
  return groups.length?`<p data-lm-risk-summary>共 ${risks.length} 条风险，按连续时间分为 ${groups.length} 段。先定位各段核对，也可直接定位具体帧。</p>`+groups.map(group=>{const time=group.clockSide?`${group.clockSide==='target'?'成片':'原片'} ${stamp(group.startFrame)}${group.endFrame!==group.startFrame?'–'+stamp(group.endFrame):''}`:'校准输入';return `<article class="lm-risk-group" data-lm-risk-group><div><strong>${time}${group.indices.length>1?` · 连续 ${group.indices.length} 帧`:''}</strong><p>${esc(group.text)}</p><button type="button" data-lm-risk="${group.firstIndex}">定位${time}</button></div>${group.indices.length>1?`<div class="lm-risk-frames"><p>逐帧定位（可直接点）</p>${group.indices.map(index=>`<button type="button" data-lm-risk="${index}">定位${Number.isInteger(risks[index].targetFrame)?'成片 '+stamp(risks[index].targetFrame):Number.isInteger(risks[index].sourceFrame)?'原片 '+stamp(risks[index].sourceFrame):'校准画面'}</button>`).join('')}</div>`:''}</article>`;}).join(''):'暂无风险记录；这不表示画面自动通过。';
}
export function localMaterialSetOldFilm(calibration,frameIndex,region){
  if(!Number.isInteger(frameIndex)||region.length<3||!calibration.shots.some(shot=>(shot.mode||'material')==='material'&&frameIndex>=shot.targetStartFrame&&frameIndex<shot.targetStartFrame+shot.targetFrames))throw new Error('请在跟随原片涂抹的成片镜头内，圈出至少3个点的实际旧面霜范围。');
  calibration.targetMaterialKeyframes=calibration.targetMaterialKeyframes.filter(key=>key.frameIndex!==frameIndex);
  calibration.targetMaterialKeyframes.push({frameIndex,region:structuredClone(region),reviewed:true});
  calibration.targetMaterialKeyframes.sort((a,b)=>a.frameIndex-b.frameIndex);
}
export function localMaterialReconstructionSettings(saved={}){
  return {sourceOcclusionReconstruction:{enabled:saved.processing?.sourceOcclusionReconstruction?.enabled===true},appearanceReconstruction:{enabled:saved.processing?.appearanceReconstruction?.enabled===true}};
}
export function localMaterialAddAppearance(calibration,frameIndex,region,presented){
  if(!presented?.ready||presented.frame!==frameIndex)throw new Error('请返回圈选的成片帧，等待实际画面确认后再保存重建区域。');
  if(!Number.isInteger(frameIndex)||!Array.isArray(region)||region.length<3||region.length>256||!region.every(p=>p&&Number.isFinite(p.x)&&Number.isFinite(p.y)&&p.x>=0&&p.x<=1&&p.y>=0&&p.y<=1)||!calibration.shots.some(shot=>(shot.mode||'material')==='material'&&frameIndex>=shot.targetStartFrame&&frameIndex<shot.targetStartFrame+shot.targetFrames))throw new Error('请在跟随原片涂抹的成片镜头内，圈出至少3个边缘点的局部重建小区域。');
  const keys=calibration.appearanceKeyframes||[];
  if(keys.length>=120)throw new Error('最多保存120个局部重建区域，请先删除不需要的记录。');
  calibration.appearanceKeyframes=[...keys,{frameIndex,region:structuredClone(region),reviewed:true}].sort((a,b)=>a.frameIndex-b.frameIndex);
}
export function localMaterialAppearanceHTML(calibration){
  return (calibration.appearanceKeyframes||[]).map((key,index)=>`<span><button type="button" data-lm-appearance-key="${index}">成片 ${(key.frameIndex/FPS).toFixed(3)}秒 · 第${key.frameIndex}帧 · 区域${index+1}</button><button type="button" data-lm-delete-appearance="${index}" aria-label="删除第${key.frameIndex}帧局部重建区域${index+1}">删除</button></span>`).join('')||'<p>尚未保存局部重建区域。每个区域只绑定这一个成片帧，不向相邻帧传播。</p>';
}
export function localMaterialForm(job){
  const d=localMaterialDefaults(job),options=(list,id)=>list.map(a=>`<option value="${esc(a.id)}" ${a.id===id?'selected':''}>${esc(a.name)}</option>`).join('');
  const range=(side,name)=>`<fieldset><legend>${name}</legend><label>从哪一秒开始<input name="${side}Start" type="number" min="0" step="any" value="${d[side+'Start']}"></label><label>到哪一秒结束<input name="${side}End" type="number" min="0" step="any" value="${d[side+'End']}"></label><label>涂抹人物<select name="${side}ActorId">${options(actors(job),d[side+'ActorId'])}</select></label></fieldset>`;
  const editor=(side,name,kind)=>`<article class="lm-editor" data-lm-editor="${side}"><h3>${name}<button type="button" data-lm-play="${side}" aria-label="播放${name}">播放${name}</button></h3><p class="lm-region-help">${side==='source'?'原片参考皮肤区域（包含膏体和周围裸肤）':'成片需要修复的皮肤区域'}</p><div class="lm-stage"><video preload="auto" playsinline muted src="/api/jobs/${encodeURIComponent(job.id)}/media/${kind}"></video><canvas tabindex="0" aria-label="${name}校准画布"></canvas></div><div class="lm-frame-controls"><button type="button" data-lm-frame="${side}:-1" aria-label="${name}上一帧">上一帧</button><label>定位秒数<input type="number" data-lm-time="${side}" min="0" step="any" value="${d[side+'Start']}"></label><button type="button" data-lm-seek="${side}" aria-label="定位${name}到填写秒数">定位</button><button type="button" data-lm-frame="${side}:1" aria-label="${name}下一帧">下一帧</button></div><input type="range" data-lm-scrub="${side}" min="0" max="${job.source.duration}" step="${1/FPS}" value="${d[side+'Start']}" aria-label="${name}时间定位"><p data-lm-frame-label="${side}"></p></article>`;
  return `<div class="lm-heading"><div><h2>保留原片真实涂抹</h2><p>已有成片的局部修复 · 本机处理 · 平台用量 0</p></div><button type="button" data-lm-close aria-label="关闭本地涂抹修复">关闭</button></div><p class="lm-intro">用于修复已有成片中的局部涂抹问题，创建新视频时无需完成这些标记。用原片实际可见的涂抹过程修复当前人物。先对齐两段画面，再保护手和长指甲、圈出同一块参考皮肤并选择当前人物自己的干净肤质。遮挡和切镜需要逐帧校准，手工标记不等于自动修复通过。原片裸肤点用于提取实际膏体，当前人物肤质用于着色，不能混用。两侧按各自完整视频的时间轴定位，局部成片的秒数不会自动套到原片。只圈同一块皮肤，不要圈全脸或清掉原片尚未揉过的额头、下巴膏点。</p><form class="lm-setup"><div class="lm-ranges">${range('source','原片动作范围')}${range('target','当前视频修复范围')}<fieldset><legend>要修复的材质</legend><label>膏体<select name="materialAssetId">${options(materials(job),d.materialAssetId)}</select></label><button type="button" data-lm-choose="source">导入另一段原片</button><input type="file" data-lm-file="source" accept=".mp4,.mov,.mkv,.webm,.avi" hidden><small data-lm-upload-name="source">默认使用此版本的原片</small></fieldset></div><button type="button" class="lm-primary" data-lm-action="create">创建本地草稿</button><button type="button" data-lm-action="refresh">查询已保存草稿</button></form><section class="lm-calibration"><h3>逐帧校准</h3><p>先划出真实切镜，选择哪些镜头跟随原片涂抹、哪些保留。把两侧停在同一涂抹镜头，再使用当前这对画面作为标定；重新标定会清空旧区域和肤色点。</p><button type="button" data-lm-action="anchor">使用当前这对画面作为标定</button><button type="button" data-lm-action="return-anchor">返回标定画面</button><button type="button" data-lm-action="clear-anchor">只清理残留，不用材料标定</button><p data-lm-anchor>尚未设置标定画面；不能用开头其他人物的脸作为涂抹标定。</p><div class="lm-tools" role="group" aria-label="校准工具"><button type="button" data-lm-tool="protect" aria-pressed="true">保护手和长甲</button><button type="button" data-lm-tool="erase" aria-pressed="false">擦除保护</button><button type="button" data-lm-tool="region" aria-pressed="false">圈选皮肤区域</button><button type="button" data-lm-tool="skin" aria-pressed="false">取干净肤色</button><button type="button" data-lm-tool="old-film" aria-pressed="false">旧面霜范围（按需）</button><label>笔刷大小<input type="range" data-lm-brush min="0.005" max="0.12" step="0.005" value="0.025"></label><button type="button" data-lm-action="undo">撤销</button></div><p class="lm-help" data-lm-tool-help>在任一画面上涂过手和长指甲。每个时刻独立保存保护标记，可继续添加任意时刻。</p><div class="lm-editors">${editor('source','原片','source')}${editor('target','当前人物','result')}</div><div class="lm-inline"><button type="button" data-lm-action="pair">保存这两帧的对应</button><button type="button" data-lm-action="cut">这里是切镜</button><button type="button" data-lm-action="clear-region">清空选中画面的圈选</button><button type="button" data-lm-action="clear-skin">清空选中画面的肤色点</button></div><div class="lm-old-film"><p>皮肤范围用于跟踪表面，不等于旧膜范围。先运行本地检查；默认只在所选皮肤表面内给出本帧旧膜候选，自动建议不是已确认事实。看到误识别时，可在成片这一帧圈实际坏白膜，按需保存；不要把正常皮肤全圈进去。</p><button type="button" data-lm-action="save-old-film">保存这帧实际旧面霜范围</button><button type="button" data-lm-action="clear-old-film">不用手绘旧膜范围，按本地建议</button><p data-lm-old-film-list></p></div><p data-lm-pairs></p><button type="button" data-lm-action="reset-shots">按所选范围重设镜头并重绘</button><div class="lm-shots" data-lm-shots></div><div class="lm-keyframes" data-lm-keyframes></div></section><section class="lm-source-reference"><h3>原片同镜头的推匀参考（可选）</h3><p>可定位到原片同一人物、同一镜头已经推匀的一帧，帮助分离材料。它属于原片，不能用作当前目标人物的干净肤质。默认仍用原片同帧裸肤点估计。</p><button type="button" data-lm-action="source-reference">这帧是原片同镜头已推匀画面</button><button type="button" data-lm-action="clear-source-reference">不用原片参考帧</button><small data-lm-source-reference-name>尚未选择原片参考帧</small><label><input type="checkbox" data-lm-source-reference-reviewed>我确认这是原片同一镜头内该人物已经推匀的画面</label></section><section class="lm-occlusion"><h3>原片被手遮挡时</h3><label><input type="checkbox" data-lm-occlusion-reconstruction>结合遮挡前后可见膏体，局部重建被遮挡区域</label><p>默认关闭。开启后仅在已校准的同一涂抹镜头内，用可见材料依据补足短暂遮挡；重建不是原片实测画面，仍需逐帧核对预览。</p></section><section class="lm-appearance"><h3>局部材质重建（可选）</h3><label><input type="checkbox" data-lm-appearance-reconstruction>允许局部材质重建（需看预览）</label><p>默认关闭，独立于原片遮挡重建。开启后可推断局部材质外观，不是当帧实测。眼、口、鼻仍受保护；已圈定的旧膜会保留，并在所选皮肤区域内补齐相连的漏边。你明确圈选的小区域可修正误分为旧手部的遮罩，须在预览中检查手指与材质。圈选只绑定当前成片这一帧，同帧可保存多个小区域，不向相邻帧传播。不要圈全脸。</p><button type="button" data-lm-tool="appearance" aria-pressed="false">圈选局部重建小区域</button><button type="button" data-lm-action="save-appearance">保存这帧重建小区域</button><button type="button" data-lm-action="clear-appearance-region">清空正在圈选的重建区域</button><p data-lm-appearance-pending>没有正在圈选的重建区域。</p><div class="lm-keyframes" data-lm-appearance-list></div></section><section class="lm-donor"><h3>当前人物自己的干净肤质</h3><p>请选脸上没有厚膏、光照相近的当前目标人物画面。其他人物的肤质不能借用。</p><button type="button" data-lm-action="donor-frame">这帧已无厚膏，用作当前人物肤质</button><button type="button" data-lm-choose="donor">导入当前人物已无厚膏的肤质图（可拖入）</button><input type="file" data-lm-file="donor" accept=".png,.jpg,.jpeg,.webp,.bmp" hidden><small data-lm-upload-name="donor">尚未选择；软件不会把结尾帧自动视为干净肤质</small><img data-lm-donor-preview alt="待人工核对的当前人物干净肤质" hidden><label><input type="checkbox" data-lm-donor-reviewed>我确认这份干净肤质属于当前目标人物</label></section><section class="lm-cleanup"><h3>切镜后的多余膏体（可选）</h3><p>先用“这里是切镜”标明两侧接头，再在当前人物上圈出切镜后多余的膏体。只处理你明确圈出的区域，默认不会清理其他部位。</p><button type="button" data-lm-tool="cleanup" aria-pressed="false">圈出当前人物残留膏体</button><div class="lm-cleanup-ranges"><label>清理从哪一秒开始<input name="cleanupStart" type="number" min="0" step="any" value="${d.targetStart}"></label><label>清理到哪一秒结束<input name="cleanupEnd" type="number" min="0" step="any" value="${d.targetEnd}"></label></div><button type="button" data-lm-action="cleanup-donor">以当前成片已无厚膏画面作此段肤质参考</button><button type="button" data-lm-action="clear-cleanup-donor">此段沿用全局肤质</button><small data-lm-cleanup-donor-name>没有单独选择，沿用全局当前人物肤质。</small><button type="button" data-lm-action="add-cleanup">我已核对，保存这个残留选区</button><button type="button" data-lm-action="clear-cleanup">清空残留清理计划</button><p data-lm-cleanup-list>没有残留清理计划。</p></section><section class="lm-risks"><h3>需要检查的画面</h3><p>先运行本地检查。点选风险帧后，在对应画面补充保护或范围标记；修改后须重新检查。</p><div class="lm-diagnostic-list" data-lm-diagnostics></div><div data-lm-risk-list>尚未检查，不代表画面通过。</div><label><input type="checkbox" data-lm-reviewed>我已检查两侧标记和全部风险帧</label></section><div class="lm-actions"><button type="button" data-lm-action="save">保存校准草稿</button><button type="button" data-lm-action="analyse">本地检查</button><button type="button" class="lm-primary" data-lm-action="render">校准完成，生成本地预览</button><button type="button" data-lm-action="cancel">暂停本地处理</button><button type="button" data-lm-action="resume">继续上次处理</button></div><p role="status" data-lm-status>请创建或取回草稿。处理不会调用外部生成平台。</p><section class="lm-result" hidden><h3>人工核对预览</h3><video data-lm-preview controls preload="metadata"></video><p>请完整播放并检查白膏是否闪回、手指是否完整、两端是否接得上。预览就绪只表示文件生成完成。</p><button type="button" class="lm-primary" data-lm-action="confirm" disabled>预览完成，保存这个版本</button></section>`;
}

const draftMemory=new Map();
const busyStates=new Set(['queued','analysing','analyzing','rendering','analysis_queued','render_queued','local_queued','processing']);
