  if(!document.querySelector('link[data-local-material-css]')){const link=document.createElement('link');link.rel='stylesheet';link.href=new URL('./local-material.css',import.meta.url).href;link.dataset.localMaterialCss='';document.head.append(link);}
  const dialog=document.createElement('dialog');dialog.className='lm-dialog';dialog.innerHTML=localMaterialForm(job);document.body.append(dialog);dialog.showModal();
  const $=selector=>dialog.querySelector(selector),$$=selector=>[...dialog.querySelectorAll(selector)];
